export const lessonBySlug=(slug:string)=>curriculum.find((lesson)=>lesson.slug===slug);

export const curriculumModules=Array.from(new Set(curriculum.map((lesson)=>lesson.module))).map((module)=>({
  module,
  lessons:curriculum.filter((lesson)=>lesson.module===module)
}));

const optionalModuleNames=new Set(["04 · Библиотека редакторов"]);

export const optionalCurriculumModules=curriculumModules.filter(group=>optionalModuleNames.has(group.module));
export const requiredCurriculum=curriculum.filter(lesson=>!optionalModuleNames.has(lesson.module));

