export const academyLevels:AcademyLevel[]=levelDefinitions.map(level=>({
  ...level,
  lessons:level.moduleNames.flatMap(moduleName=>curriculum.filter(lesson=>lesson.module===moduleName)),
}));

export const finalAssessmentIndex=academyLevels.length;

export type AcademyStep=
  |{kind:"lesson";lesson:Lesson}
  |{kind:"assessment";moduleIndex:number;label:string;final:boolean}
  |{kind:"complete"};

export type LessonAccess={
  unlocked:boolean;
  reason:"available"|"completed"|"sequence"|"assessment"|"before-start"|"missing";
};

export function academyLevelIndexForLesson(slug:string){
  return academyLevels.findIndex(level=>level.lessons.some(lesson=>lesson.slug===slug));
}

export function academyStartLevelIndex(level:unknown){
  const startSlug=learningStarts[normalizeExperienceLevel(level)].slug;
  const index=academyLevelIndexForLesson(startSlug);
  return index>=0?index:0;
}

function lessonsRequiredFromStart(level:unknown){
  const startIndex=learningStartIndex(level);
  const startSlug=curriculum[startIndex]?.slug;
  const startLevelIndex=academyStartLevelIndex(level);
  return academyLevels.flatMap((academyLevel,index)=>{
    if(index<startLevelIndex)return [];
    if(index>startLevelIndex)return academyLevel.lessons;
    const lessonIndex=academyLevel.lessons.findIndex(lesson=>lesson.slug===startSlug);
    return lessonIndex>=0?academyLevel.lessons.slice(lessonIndex):academyLevel.lessons;
  });
}

export function lessonAccess(slug:string,completedSlugs:string[],passedAssessments:number[],level:unknown):LessonAccess{
  const lessonIndex=curriculum.findIndex(item=>item.slug===slug);
  if(lessonIndex<0)return {unlocked:false,reason:"missing"};

  const completed=new Set(completedSlugs);
  if(completed.has(slug))return {unlocked:true,reason:"completed"};

  const lessonLevelIndex=academyLevelIndexForLesson(slug);
  if(lessonLevelIndex<0)return {unlocked:true,reason:"available"};

  const startLevelIndex=academyStartLevelIndex(level);
  const startSlug=learningStarts[normalizeExperienceLevel(level)].slug;
  const levelLessons=academyLevels[lessonLevelIndex].lessons;
  const startPosition=lessonLevelIndex===startLevelIndex
    ?Math.max(0,levelLessons.findIndex(item=>item.slug===startSlug))
    :0;
  const lessonPosition=levelLessons.findIndex(item=>item.slug===slug);

  if(lessonLevelIndex<startLevelIndex||lessonPosition<startPosition){
    return {unlocked:true,reason:"before-start"};
  }

  for(let index=startLevelIndex;index<lessonLevelIndex;index++){
    if(!passedAssessments.includes(index))return {unlocked:false,reason:"assessment"};
  }

  const requiredBefore=levelLessons.slice(startPosition,lessonPosition);
  if(requiredBefore.some(item=>!completed.has(item.slug))){
    return {unlocked:false,reason:"sequence"};
  }

  return {unlocked:true,reason:"available"};
}

export function nextAvailableLesson(completedSlugs:string[],passedAssessments:number[],level:unknown){
  return lessonsRequiredFromStart(level).find(lesson=>{
    if(completedSlugs.includes(lesson.slug))return false;
    return lessonAccess(lesson.slug,completedSlugs,passedAssessments,level).unlocked;
  });
}

export function assessmentAvailable(levelIndex:number,completedSlugs:string[],passedAssessments:number[],level:unknown){
  if(levelIndex<0||levelIndex>finalAssessmentIndex||passedAssessments.includes(levelIndex))return false;
  const startLevelIndex=academyStartLevelIndex(level);
  if(levelIndex<startLevelIndex)return false;
  const completed=new Set(completedSlugs);
  if(levelIndex===finalAssessmentIndex){
    return lessonsRequiredFromStart(level).every(item=>completed.has(item.slug))
      &&Array.from({length:finalAssessmentIndex-startLevelIndex},(_,offset)=>startLevelIndex+offset).every(index=>passedAssessments.includes(index));
  }
  const required=assessmentRequiredLessons(levelIndex,level);
  return required.length>0&&required.every(item=>completed.has(item.slug))
    &&Array.from({length:levelIndex-startLevelIndex},(_,offset)=>startLevelIndex+offset).every(index=>passedAssessments.includes(index));
}

export function nextAcademyStep(completedSlugs:string[],passedAssessments:number[],level:unknown):AcademyStep{
  const startLevelIndex=academyStartLevelIndex(level);
  for(let levelIndex=startLevelIndex;levelIndex<academyLevels.length;levelIndex++){
    if(assessmentAvailable(levelIndex,completedSlugs,passedAssessments,level)){
      return {kind:"assessment",moduleIndex:levelIndex,label:`Аттестация «${academyLevels[levelIndex].name}»`,final:false};
    }
    const lesson=assessmentRequiredLessons(levelIndex,level).find(item=>
      !completedSlugs.includes(item.slug)&&lessonAccess(item.slug,completedSlugs,passedAssessments,level).unlocked
    );
    if(lesson)return {kind:"lesson",lesson};
  }
  if(assessmentAvailable(finalAssessmentIndex,completedSlugs,passedAssessments,level))return {kind:"assessment",moduleIndex:finalAssessmentIndex,label:"Выпускной экзамен",final:true};
  return {kind:"complete"};
}

export function assessmentRequiredLessons(levelIndex:number,level:unknown){
  const academyLevel=academyLevels[levelIndex];
  if(!academyLevel)return [];
  const startLevelIndex=academyStartLevelIndex(level);
  if(levelIndex<startLevelIndex)return [];
  if(levelIndex>startLevelIndex)return academyLevel.lessons;

  const startSlug=learningStarts[normalizeExperienceLevel(level)].slug;
  const firstRequiredIndex=academyLevel.lessons.findIndex(item=>item.slug===startSlug);
  return firstRequiredIndex>=0?academyLevel.lessons.slice(firstRequiredIndex):academyLevel.lessons;
}

export const curriculumStats={
  lessons:requiredCurriculum.length,
  minutes:requiredCurriculum.reduce((total,lesson)=>total+lesson.minutes,0),
  assignments:requiredCurriculum.filter(lesson=>!lesson.theoryOnly).length,
  theory:requiredCurriculum.filter(lesson=>lesson.theoryOnly).length,
  optional:curriculum.length-requiredCurriculum.length,
};

export const curriculumExperience=requiredCurriculum.reduce((total,lesson)=>total+lesson.xp,0);
